import React from 'react';

const NavItem = ({ onClick, icon, label }) => (
  <button onClick={onClick} className="flex items-center px-3 py-2 text-sm text-gray-700 dark:text-white hover:bg-gray-100 dark:hover:bg-gray-800 rounded-md">
    {icon && <span className="mr-2">{icon}</span>}
    {label}
  </button>
);

export default NavItem;
